async function callSDK(
  systemPrompt: string,
  userPrompt: string,
  maxTokens?: number
): Promise<LlmResult> {
  const start = Date.now();
  try {
    const zai = await ZAI.create();
    const completion = await zai.chat.completions.create({
      messages: [
