        { role: 'user', content: userPrompt },
      ],
      max_tokens: maxTokens,
      thinking: { type: 'disabled' },
    });
    const text = completion.choices?.[0]?.message?.content || null;
    return { text, provider: 'SDK', latencyMs: Date.now() - start };
  } catch (err: unknown) {
